INSERT INTO resources(id,title,organisation,category,summary,url,licence,licence_url,access_status,potential_role,notes,last_reviewed_at,verified,status) VALUES('igboapi','Nkọwa okwu / IgboAPI','Nkọwa okwu','Pronunciation / Linguistics','Dialect-aware dictionary entries, meanings, example sentences and pronunciation recordings. A relevant starting point for lexical and dialect research.','https://docs.igboapi.com/igbo_api/overview','API terms; data and audio rights require review','https://igboapi.com/terms','Permission review','Potential collaboration','API access does not itself grant unrestricted training or redistribution rights. Review each data release and obtain permission where necessary.','2026-09-05','0','Published');
INSERT INTO resources(id,title,organisation,category,summary,url,licence,licence_url,access_status,potential_role,notes,last_reviewed_at,verified,status) VALUES('waxal','Google WAXAL — Igbo TTS','Google Research / Media Trust','Dataset','High-quality recorded speech for TTS research and possible baseline development. The Igbo subset is listed under Media Trust in the current dataset card.','https://huggingface.co/datasets/google/WaxalNLP','CC BY-SA 4.0 for the listed Igbo TTS subset','https://huggingface.co/datasets/google/WaxalNLP','Share-alike review','Reuse','Initial assessment of the current card: licences differ by provider. Audit the chosen version, attribution, share-alike obligations and recording provenance before reuse.','2026-09-05','0','Published');
INSERT INTO resources(id,title,organisation,category,summary,url,licence,licence_url,access_status,potential_role,notes,last_reviewed_at,verified,status) VALUES('common-voice','Mozilla Common Voice — Igbo','Mozilla Foundation / Common Voice','Dataset','Community read speech relevant to ASR, speaker variation and robustness. Review validated splits and sampling coverage before experiments.','https://mozilladatacollective.com/datasets/cmqioflak00zwnr073z9m9cra','CC0-1.0; platform conditions also apply','https://mozilladatacollective.com/datasets/cmqioflak00zwnr073z9m9cra','Platform conditions','Reuse','Reviewed release: Scripted Speech 26.0, June 2026. The datasheet prohibits speaker identification and re-hosting or re-sharing. Record access terms separately from the licence label.','2026-09-05','0','Published');
INSERT INTO resources(id,title,organisation,category,summary,url,licence,licence_url,access_status,potential_role,notes,last_reviewed_at,verified,status) VALUES('fleurs','Google FLEURS','Google Research','Dataset','Multilingual speech benchmark including Igbo, useful for comparative ASR evaluation and reproducible evaluation splits.','https://huggingface.co/datasets/google/fleurs','CC BY 4.0; verify selected release','https://huggingface.co/datasets/google/fleurs','Attribution review','Benchmark','Keep benchmark test data separate from training. Review domain, dialect and speaker coverage rather than treating one benchmark as complete language coverage.','2026-09-05','0','Published');
INSERT INTO resources(id,title,organisation,category,summary,url,licence,licence_url,access_status,potential_role,notes,last_reviewed_at,verified,status) VALUES('african-voices','African Voices / Data Science Nigeria','Data Science Nigeria','Dataset','Nigerian-language speech including Igbo, potentially significant for speech research. Metadata and permissions need a formal audit before ingestion.','https://africanvoices.io/terms-of-use','CC BY 4.0 default stated alongside platform restrictions','https://africanvoices.io/terms-of-use','Permission review','Investigate','Reconcile dataset-specific permissions and platform terms, review consent and version provenance. This is the Data Science Nigeria platform, distinct from other projects with similar names.','2026-09-05','0','Published');
INSERT INTO resources(id,title,organisation,category,summary,url,licence,licence_url,access_status,potential_role,notes,last_reviewed_at,verified,status) VALUES('ikengatts','IkengaTTS','chimezie90','TTS','An Igbo F5-TTS adaptation demonstrating meaningful ongoing Igbo speech synthesis work. An important reference for future comparison.','https://huggingface.co/chimezie90/igbo-tts-f5','CC BY-NC-SA 4.0 stated by model card','https://huggingface.co/chimezie90/igbo-tts-f5/blob/main/README.md','Non-commercial restrictions','Benchmark','Respect the model, base-model and data conditions. Published performance claims have not been independently reproduced by Igbo AI. Investigate explicit tone, phoneme and dialect supervision through controlled comparisons.','2026-09-05','0','Published');
INSERT INTO resources(id,title,organisation,category,summary,url,licence,licence_url,access_status,potential_role,notes,last_reviewed_at,verified,status) VALUES('mms','Meta MMS','Meta AI','ASR','Multilingual ASR and TTS research baselines. Model families and language checkpoints must be checked individually.','https://huggingface.co/facebook/mms-tts','TTS weights: CC BY-NC 4.0','https://huggingface.co/facebook/mms-tts','Non-commercial restrictions','Benchmark','MMS is a research/reference baseline, not an assumed permissive production foundation. Confirm Igbo coverage for the exact task and checkpoint before evaluation.','2026-09-05','0','Published');
INSERT INTO resources(id,title,organisation,category,summary,url,licence,licence_url,access_status,potential_role,notes,last_reviewed_at,verified,status) VALUES('ncair-asr','NCAIR / Awarri — Igbo ASR','NCAIR / Awarri','ASR','An Igbo Whisper Small adaptation within Nigerian language AI initiatives. Evidence of an active national speech research ecosystem.','https://huggingface.co/NCAIR1/Igbo-ASR','Custom research and innovation terms','https://huggingface.co/NCAIR1/Igbo-ASR?library=transformers','Permission review','Benchmark','The published terms include attribution, use limits and separate commercial licensing. Audit exact release terms before use. No partnership with Igbo AI is implied.','2026-09-05','0','Published');
INSERT INTO resources(id,title,organisation,category,summary,url,licence,licence_url,access_status,potential_role,notes,last_reviewed_at,verified,status) VALUES('natlas','N-ATLaS','NCAIR / Awarri','Language Model','A multilingual language model with Igbo among its target languages. A reference for later language-understanding evaluation.','https://huggingface.co/NCAIR1/N-ATLaS','Release and base-model conditions require review','https://huggingface.co/NCAIR1/N-ATLaS','Further licence audit required','Investigate','Review model and underlying Llama conditions independently. Igbo AI has not independently evaluated this model or confirmed a collaboration.','2026-09-05','0','Published');
INSERT INTO resources(id,title,organisation,category,summary,url,licence,licence_url,access_status,potential_role,notes,last_reviewed_at,verified,status) VALUES('igbobert','IgboBERT','Chukwuneke, Ezeani, Rayson and El-Haj','NLP','Igbo-specific transformer representations and named entity recognition research. Prior work that can inform future text-processing and language-understanding experiments.','https://aclanthology.org/2022.lrec-1.547/','Paper access does not establish model/data reuse rights','https://aclanthology.org/2022.lrec-1.547/','Further licence audit required','Investigate','LREC 2022. Verify checkpoint and corpus licences separately. Possible relevance to normalisation and diacritics is a future research direction, not a demonstrated capability claimed here.','2026-09-05','0','Published');
INSERT INTO resources(id,title,organisation,category,summary,url,licence,licence_url,access_status,potential_role,notes,last_reviewed_at,verified,status) VALUES('igboberta','IgboBERTa','AfricaNLP 2024 research contribution','NLP','Igbo text representation research, including evaluation on named entity recognition. A further reference for Igbo NLP.','https://openreview.net/pdf?id=OmCAN790Qj','Checkpoint and corpus terms require review','https://openreview.net/pdf?id=OmCAN790Qj','Further licence audit required','Investigate','Paper identified through its indexed AfricaNLP 2024 record. Full-text retrieval required a browser challenge during this review; verify the complete paper, authorship and artefacts before reuse.','2026-09-05','0','Published');
INSERT INTO resources(id,title,organisation,category,summary,url,licence,licence_url,access_status,potential_role,notes,last_reviewed_at,verified,status) VALUES('masakhane','Masakhane','Masakhane research community','Research Community','An African NLP ecosystem covering translation, named entity recognition, classification, question answering and evaluation.','https://www.masakhane.io','Resource-specific licences','https://github.com/masakhane-io','Further licence audit required','Potential collaboration','Engage respectfully with existing researchers. Each dataset, model and code repository has its own terms and language coverage. Community membership does not establish a formal project partnership.','2026-09-05','0','Published');
